#include <algorithm>
#include <memory>
#include <queue>
#include <sstream>
#include <string>
#include <unordered_map>
#include <vector>

struct Node
{
    int value;
    std::unique_ptr<Node> left, right;
};

int height(const Node* root)
{
    if (!root) return -1;
    return 1 + std::max(height(root->left.get()), height(root->right.get()));
}

bool sameTree(const Node* a, const Node* b)
{
    if (!a || !b) return a == b;
    return a->value == b->value && sameTree(a->left.get(), b->left.get()) && sameTree(a->right.get(), b->right.get());
}

std::vector<int> postorder(const Node* root)
{
    // A pre-order that visits right before left, reversed, is a post-order.
    std::vector<int> out;
    std::vector<const Node*> stack;
    if (root) stack.push_back(root);
    while (!stack.empty())
    {
        const Node* n = stack.back();
        stack.pop_back();
        out.push_back(n->value);
        if (n->left) stack.push_back(n->left.get());
        if (n->right) stack.push_back(n->right.get());
    }
    std::reverse(out.begin(), out.end());
    return out;
}

std::vector<std::vector<int>> levels(const Node* root)
{
    std::vector<std::vector<int>> out;
    std::queue<const Node*> q;
    if (root) q.push(root);
    while (!q.empty())
    {
        out.emplace_back();
        for (std::size_t count = q.size(); count > 0; --count)
        {
            const Node* n = q.front();
            q.pop();
            out.back().push_back(n->value);
            if (n->left) q.push(n->left.get());
            if (n->right) q.push(n->right.get());
        }
    }
    return out;
}

static std::unique_ptr<Node> buildRange(const std::vector<int>& pre, std::size_t& next, const std::unordered_map<int, int>& where, int lo, int hi)
{
    if (lo > hi) return nullptr;
    int value = pre[next++];
    int mid = where.at(value);
    auto n = std::make_unique<Node>(Node{ value, nullptr, nullptr });
    n->left = buildRange(pre, next, where, lo, mid - 1);
    n->right = buildRange(pre, next, where, mid + 1, hi);
    return n;
}

std::unique_ptr<Node> build(const std::vector<int>& pre, const std::vector<int>& in)
{
    std::unordered_map<int, int> where;
    for (int i = 0; i < static_cast<int>(in.size()); ++i) where[in[i]] = i;
    std::size_t next = 0;
    return buildRange(pre, next, where, 0, static_cast<int>(in.size()) - 1);
}

static void write(const Node* n, std::string& out)
{
    if (!out.empty()) out += ' ';
    if (!n) { out += '#'; return; }
    out += std::to_string(n->value);
    write(n->left.get(), out);
    write(n->right.get(), out);
}

std::string serialize(const Node* root)
{
    std::string out;
    write(root, out);
    return out;
}

static std::unique_ptr<Node> read(std::istringstream& in)
{
    std::string token;
    if (!(in >> token) || token == "#") return nullptr;
    auto n = std::make_unique<Node>(Node{ std::stoi(token), nullptr, nullptr });
    n->left = read(in);
    n->right = read(in);
    return n;
}

std::unique_ptr<Node> deserialize(const std::string& text)
{
    std::istringstream in(text);
    return read(in);
}

unitTests:
static std::unique_ptr<Node> leaf(int v) { return std::make_unique<Node>(Node{ v, nullptr, nullptr }); }
static std::unique_ptr<Node> node(int v, std::unique_ptr<Node> l, std::unique_ptr<Node> r) { return std::make_unique<Node>(Node{ v, std::move(l), std::move(r) }); }
static std::unique_ptr<Node> sample() { return node(8, node(3, leaf(1), node(6, leaf(4), leaf(7))), node(10, nullptr, node(14, leaf(13), nullptr))); }

static std::unique_ptr<Node> perfect(int lo, int hi)        // a perfect tree over lo..hi, root in the middle
{
    if (lo > hi) return nullptr;
    int mid = (lo + hi) / 2;
    return node(mid, perfect(lo, mid - 1), perfect(mid + 1, hi));
}
static void preOf(const Node* n, std::vector<int>& out) { if (!n) return; out.push_back(n->value); preOf(n->left.get(), out); preOf(n->right.get(), out); }

TEST("height and equality") {
    auto t = sample();
    CHECK_EQ(height(t.get()), 3);
    CHECK_EQ(height(nullptr), -1);
    CHECK_EQ(height(leaf(5).get()), 0);
    CHECK(sameTree(t.get(), sample().get()));
    auto other = sample();
    other->right->right->left->value = 12;
    CHECK(!sameTree(t.get(), other.get()));
    CHECK(!sameTree(t.get(), nullptr));
    CHECK(sameTree(nullptr, nullptr));
}
TEST("post-order without recursion") {
    CHECK_EQ(postorder(sample().get()), (std::vector<int>{ 1, 4, 7, 6, 3, 13, 14, 10, 8 }));
    CHECK(postorder(nullptr).empty());
    std::unique_ptr<Node> deep;                              // a chain 100,000 levels deep
    Node* tail = nullptr;
    for (int i = 0; i < 100000; ++i)
    {
        auto n = leaf(i);
        Node* raw = n.get();
        if (tail) tail->left = std::move(n); else deep = std::move(n);
        tail = raw;
    }
    std::vector<int> order = postorder(deep.get());
    CHECK_EQ(order.size(), std::size_t{ 100000 });
    CHECK_EQ(order.empty() ? -1 : order.front(), 99999);
    CHECK_EQ(order.empty() ? -1 : order.back(), 0);
    for (Node* n = deep.get(); n && n->left;) n->left = std::move(n->left->left);   // free it without deep recursion
}
TEST("levels") {
    CHECK_EQ(levels(sample().get()), (std::vector<std::vector<int>>{ { 8 }, { 3, 10 }, { 1, 6, 14 }, { 4, 7, 13 } }));
    CHECK(levels(nullptr).empty());
}
TEST("rebuilding from two traversals") {
    auto t = build({ 8, 3, 1, 6, 4, 7, 10, 14, 13 }, { 1, 3, 4, 6, 7, 8, 10, 13, 14 });
    CHECK(sameTree(t.get(), sample().get()));
    CHECK(build({}, {}) == nullptr);
    auto big = perfect(1, 65535);
    std::vector<int> pre, in;
    preOf(big.get(), pre);
    for (int i = 1; i <= 65535; ++i) in.push_back(i);
    auto rebuilt = build(pre, in);
    CHECK(sameTree(rebuilt.get(), big.get()));
}
TEST("serialising") {
    CHECK_EQ(serialize(node(2, leaf(1), nullptr).get()), std::string("2 1 # # #"));
    CHECK_EQ(serialize(nullptr), std::string("#"));
    CHECK_EQ(serialize(sample().get()), std::string("8 3 1 # # 6 4 # # 7 # # 10 # 14 13 # # #"));
    auto back = deserialize(serialize(sample().get()));
    CHECK(sameTree(back.get(), sample().get()));
    CHECK(deserialize("#") == nullptr);
    auto neg = deserialize("-5 # -7 # #");
    CHECK(neg && neg->right);
    if (neg && neg->right) { CHECK_EQ(neg->value, -5); CHECK_EQ(neg->right->value, -7); }
}

